#!/bin/bash
# Test: project-local (cloud-compatible) bundle generated by scripts/build-project-local.py

setup_test "Project-Local Bundle"

BUILD="$REPO_ROOT/scripts/build-project-local.py"

# Test 1: committed bundle is in sync with skills/, agents/, refs/
check_out=$(python3 "$BUILD" --check 2>&1)
if [ $? -eq 0 ]; then
    pass_test "Committed .claude/ bundle and CLAUDE.md are up to date with sources"
else
    fail_test "Committed .claude/ bundle is up to date" "$check_out"
fi

# Test 2: installing into a fresh project produces every skill, agent and ref
pl_tmp=$(mktemp -d)
python3 "$BUILD" --target "$pl_tmp" > /dev/null 2>&1
missing=""
for d in "$REPO_ROOT"/skills/*/; do
    n=$(basename "$d"); [ -f "$pl_tmp/.claude/skills/$n/SKILL.md" ] || missing="$missing skills/$n"
done
for f in "$REPO_ROOT"/agents/*.md; do
    n=$(basename "$f"); [ -f "$pl_tmp/.claude/agents/$n" ] || missing="$missing agents/$n"
done
for f in "$REPO_ROOT"/refs/*.md; do
    n=$(basename "$f"); [ -f "$pl_tmp/.claude/ideaprobe/refs/$n" ] || missing="$missing refs/$n"
done
if [ -z "$missing" ]; then
    pass_test "Install into a fresh project creates all skills, agents and refs"
else
    fail_test "Install creates all files" "missing:$missing"
fi

# Test 3: no plugin-only references remain (namespaced agents, plugin-relative refs)
leftover=$(grep -rnoE 'ideaprobe:[a-z-]+|IdeaProbe plugin directory|(^|[^/a-z.-])refs/[a-z-]+\.md' \
    "$pl_tmp/.claude/skills" "$pl_tmp/.claude/agents" | grep -v 'ideaprobe:` prefix' || true)
if [ -z "$leftover" ]; then
    pass_test "Generated files contain no plugin-only references"
else
    fail_test "Generated files contain no plugin-only references" "$leftover"
fi

# Test 4: every .claude/ideaprobe/refs/ path mentioned in the bundle exists
broken=""
for p in $(grep -rhoE '\.claude/ideaprobe/refs/[A-Za-z0-9_-]+\.md' "$pl_tmp/.claude" "$pl_tmp/CLAUDE.md" | sort -u); do
    [ -f "$pl_tmp/$p" ] || broken="$broken $p"
done
if [ -z "$broken" ]; then
    pass_test "All bundle ref paths resolve"
else
    fail_test "All bundle ref paths resolve" "broken:$broken"
fi

# Test 5: CLAUDE.md bootstrap is idempotent and preserves existing content
printf '# My Project\n\nKeep me.\n' > "$pl_tmp/CLAUDE.md"
python3 "$BUILD" --target "$pl_tmp" > /dev/null 2>&1
python3 "$BUILD" --target "$pl_tmp" > /dev/null 2>&1
blocks=$(grep -c 'ideaprobe:begin' "$pl_tmp/CLAUDE.md")
if [ "$blocks" = "1" ] && grep -q 'Keep me.' "$pl_tmp/CLAUDE.md"; then
    pass_test "CLAUDE.md bootstrap block is idempotent and keeps user content"
else
    fail_test "CLAUDE.md bootstrap block is idempotent" "blocks=$blocks"
fi

# Test 6: manifest version matches plugin version
mv_plugin=$(python3 -c "import json;print(json.load(open('$REPO_ROOT/.claude-plugin/plugin.json'))['version'])")
mv_bundle=$(python3 -c "import json;print(json.load(open('$REPO_ROOT/.claude/ideaprobe/manifest.json'))['version'])")
if [ "$mv_plugin" = "$mv_bundle" ]; then
    pass_test "Bundle manifest version matches plugin.json ($mv_plugin)"
else
    fail_test "Bundle manifest version matches plugin.json" "plugin=$mv_plugin bundle=$mv_bundle"
fi

rm -rf "$pl_tmp"
